div.script:
(function () {
  'use strict';

  var FILTER_ID = 6;
  var DESIRED_LIMIT = 500;
  var MARKER_ID = 'dyn_snippet_debug_meta';
  var FALLBACK_ID = 'dyn_snippet_debug_fallback';

  var fallbackNode = null;
  var requestFrame = (window.requestAnimationFrame && window.requestAnimationFrame.bind(window)) || function (cb) { return setTimeout(cb, 0); };

  function normaliseArgs(args) {
    return Array.prototype.map.call(args, function (value) {
      if (typeof value === 'string') {
        return value;
      }
      try {
        return JSON.stringify(value);
      } catch (err) {
        return String(value);
      }
    }).join(' ');
  }

  function appendFallback(level, args) {
    if (!fallbackNode) {
      fallbackNode = document.getElementById(FALLBACK_ID);
    }
    if (!fallbackNode) {
      return;
    }
    var entry = document.createElement('div');
    entry.setAttribute('data-level', level);
    entry.textContent = '[' + level + '] ' + normaliseArgs(args);
    fallbackNode.appendChild(entry);
  }

  function callConsole(level, args, altLevel) {
    var c = window.console || null;
    if (c) {
      var fn = typeof c[level] === 'function' ? c[level] : null;
      if (!fn && altLevel && typeof c[altLevel] === 'function') {
        fn = c[altLevel];
      }
      if (fn) {
        try {
          fn.apply(c, args);
        } catch (err) {
          // Ignore console failures but keep fallback output
        }
      }
    }
    if (level !== 'table') {
      appendFallback(level, args);
    }
  }

  var consoleProxy = {
    log: function () {
      callConsole('log', arguments, 'debug');
    },
    info: function () {
      callConsole('info', arguments, 'log');
    },
    warn: function () {
      callConsole('warn', arguments, 'log');
    },
    error: function () {
      callConsole('error', arguments, 'log');
    },
    group: function () {
      callConsole('group', arguments, 'log');
    },
    groupEnd: function () {
      callConsole('groupEnd', arguments, 'log');
    },
    table: function (rows) {
      var c = window.console || null;
      if (c && typeof c.table === 'function') {
        try {
          c.table(rows);
        } catch (err) {
          callConsole('log', [rows], 'log');
        }
      } else {
        callConsole('log', [rows], 'log');
      }
      appendFallback('table', [rows]);
    }
  };

  function parseIntOrDefault(value, fallback) {
    var parsed = parseInt(value, 10);
    return isNaN(parsed) ? fallback : parsed;
  }

  function bootstrapDiagnostics() {
    consoleProxy.group('[dyn-snippet] Diagnostics bootstrap');
    try {
      var marker = document.getElementById(MARKER_ID);
      if (!marker) {
        consoleProxy.warn('[dyn-snippet] Debug marker element not found; diagnostics disabled.');
        return;
      }

      var data = marker.dataset || {};
      consoleProxy.info('Marker dataset captured:', data);

      var snippetExists = data.snippetExists === '1';
      var serverLimit = parseIntOrDefault(data.serverLimit || '0', 0);
      var serverModelName = data.serverModelName || '';
      var serverFilterName = data.serverFilterName || '';
      var serverFilterDomainRepr = data.serverFilterDomain || '';
      var serverLegacyDomainRepr = data.serverLegacyDomain || '';
      var hasFilterDomainField = data.hasFilterDomain === '1';
      var hasLegacyDomainField = data.hasLegacyDomain === '1';

      var secSelector = 'section.s_dynamic_snippet_products[data-template-key="website_sale.dynamic_filter_template_product_product_mini_name"][data-filter-id="' + FILTER_ID + '"]';
      var sec = document.querySelector(secSelector);

      if (!sec) {
        consoleProxy.warn('[dyn-snippet] Section not found for selector:', secSelector);
        return;
      }

      var limitString = String(DESIRED_LIMIT);
      sec.dataset.numberOfRecords = limitString;
      sec.dataset.nbRecords = limitString;
      sec.dataset.limit = limitString;
      sec.setAttribute('data-number-of-records', limitString);
      sec.setAttribute('data-nb-records', limitString);
      sec.setAttribute('data-limit', limitString);

      consoleProxy.info('[dyn-snippet] Enforced dataset limit attributes to', DESIRED_LIMIT);

      var requested = parseIntOrDefault(
        sec.dataset.numberOfRecords ||
          sec.dataset.nbRecords ||
          sec.getAttribute('data-number-of-records') ||
          sec.getAttribute('data-nb-records') ||
          sec.getAttribute('data-limit') ||
          '0',
        0
      );

      var effectiveCap = Math.max(serverLimit || 0, 16);

      consoleProxy.info('Filter name (DB):', serverFilterName || '(missing)');
      consoleProxy.info('Filter model (DB):', serverModelName || '(missing)');
      consoleProxy.info('Snippet exists in database:', snippetExists);
      consoleProxy.info('Server limit (DB):', serverLimit);
      consoleProxy.info('Effective cap enforced in _prepare_values():', effectiveCap);
      consoleProxy.info('Has filter_domain field:', hasFilterDomainField);
      consoleProxy.info('Has legacy domain field:', hasLegacyDomainField);
      if (serverFilterDomainRepr) {
        consoleProxy.info('filter_domain repr:', serverFilterDomainRepr);
      } else if (hasFilterDomainField) {
        consoleProxy.warn('filter_domain field present but empty.');
      } else {
        consoleProxy.warn('filter_domain field unavailable on this database.');
      }

      if (serverLegacyDomainRepr) {
        consoleProxy.info('legacy domain repr:', serverLegacyDomainRepr);
      } else if (hasLegacyDomainField) {
        consoleProxy.warn('legacy domain field present but empty.');
      } else {
        consoleProxy.warn('legacy domain field unavailable on this database.');
      }

      consoleProxy.info('Section data attributes after enforcement:', {
        templateKey: sec.getAttribute('data-template-key'),
        filterId: sec.getAttribute('data-filter-id'),
        categoryId: sec.getAttribute('data-product-category-id'),
        nbRecords: sec.getAttribute('data-nb-records'),
        numberOfRecords: sec.getAttribute('data-number-of-records'),
        limit: sec.getAttribute('data-limit')
      });

      if (!snippetExists || serverLimit === 0) {
        consoleProxy.warn('[dyn-snippet] The filter record was not found or reports a limit of 0.');
      } else if (requested > effectiveCap) {
        consoleProxy.warn('[dyn-snippet] Requested', requested, 'but capped to', effectiveCap, 'by server logic.');
      } else {
        consoleProxy.info('[dyn-snippet] Requested count within cap:', requested);
      }

      function countItems() {
        var cards = sec.querySelectorAll('.o_dynamic_product_hovered');
        consoleProxy.info('[dyn-snippet] Actually rendered items:', cards.length);

        if (!cards.length) {
          consoleProxy.warn('[dyn-snippet] No .o_dynamic_product_hovered cards were found during count.');
          return;
        }

        var debugRows = [];
        Array.prototype.forEach.call(cards, function (card, idx) {
          var contextEl = card.querySelector('[data-oe-model]');
          var linkEl = card.querySelector('a.o_carousel_product_img_link');
          var row = {
            index: idx,
            href: linkEl ? linkEl.getAttribute('href') : null,
            oeModel: contextEl ? contextEl.getAttribute('data-oe-model') : null,
            oeId: contextEl ? contextEl.getAttribute('data-oe-id') : null
          };
          var dataset = {};
          if (card.dataset) {
            Object.keys(card.dataset).forEach(function (key) {
              dataset[key] = card.dataset[key];
            });
          }
          row.dataset = dataset;
          if (!row.oeModel && dataset.dynSourceModel) {
            row.oeModel = dataset.dynSourceModel;
          }
          if (!row.oeId && dataset.dynSourceId) {
            row.oeId = dataset.dynSourceId;
          }
          if (contextEl && contextEl.hasAttribute('data-oe-context')) {
            try {
              row.context = JSON.parse(contextEl.getAttribute('data-oe-context') || '{}');
            } catch (err) {
              row.context = '[parse-error]';
              consoleProxy.warn('[dyn-snippet] Failed to parse data-oe-context JSON for card', idx, err);
            }
          }
          debugRows.push(row);
        });

        consoleProxy.table(debugRows);

        var serverDebugRows = [];
        var debugContainers = sec.querySelectorAll('.dyn-snippet-debug-records');
        if (debugContainers.length) {
          Array.prototype.forEach.call(debugContainers, function (container) {
            var rows = container.querySelectorAll('.dyn-snippet-debug-record');
            Array.prototype.forEach.call(rows, function (node) {
              var ds = node.dataset || {};
              serverDebugRows.push({
                index: parseIntOrDefault(ds.index || '-1', -1),
                added: ds.added === '1',
                sourceModel: ds.sourceModel || null,
                sourceId: ds.sourceId || null,
                templateId: ds.templateId || null,
                templateModel: ds.templateModel || null,
                templateName: ds.templateName || null,
                rawKeys: ds.rawKeys || ''
              });
            });
            if (container.parentNode) {
              container.parentNode.removeChild(container);
            }
          });
        }

        if (serverDebugRows.length) {
          consoleProxy.table(serverDebugRows);
          var serverAddedCount = serverDebugRows.filter(function (row) { return row.added; }).length;
          if (serverAddedCount !== cards.length) {
            consoleProxy.warn('[dyn-snippet] Difference between server-added count (' + serverAddedCount + ') and rendered cards (' + cards.length + ') indicates client-side HTML was pruned, possibly by template duplicates or missing data.');
          } else {
            consoleProxy.info('[dyn-snippet] Server-added count matches rendered card count:', serverAddedCount);
          }
          var droppedRows = serverDebugRows.filter(function (row) { return !row.added; });
          if (droppedRows.length) {
            consoleProxy.warn('[dyn-snippet] Server skipped records due to duplicate template IDs before render.', droppedRows);
          }
        } else {
          consoleProxy.warn('[dyn-snippet] No server-side debug metadata found inside the snippet; template instrumentation may be missing.');
        }

        var templateStats = {};
        var sourceStats = {};
        debugRows.forEach(function (row) {
          var ds = row.dataset || {};
          var templateId = ds.dynTemplateId || ds.dynId || null;
          var templateKey = templateId ? String(templateId) : '(missing)';
          if (!templateStats[templateKey]) {
            templateStats[templateKey] = {
              count: 0,
              rows: [],
              model: ds.dynTemplateModel || null,
              name: ds.dynTemplateName || null
            };
          }
          templateStats[templateKey].count += 1;
          templateStats[templateKey].rows.push(row.index);

          var sourceKey = (row.oeModel || '(unknown)') + ':' + (row.oeId || '(unknown)');
          if (!sourceStats[sourceKey]) {
            sourceStats[sourceKey] = { count: 0, rows: [] };
          }
          sourceStats[sourceKey].count += 1;
          sourceStats[sourceKey].rows.push(row.index);
        });

        var duplicateTemplates = Object.keys(templateStats)
          .map(function (key) { return { key: key, data: templateStats[key] }; })
          .filter(function (item) { return item.data.count > 1; });

        if (duplicateTemplates.length) {
          consoleProxy.warn('[dyn-snippet] Duplicate product templates detected; cards referencing the same template ID will be hidden.', duplicateTemplates);
        }

        var duplicateSources = Object.keys(sourceStats)
          .map(function (key) { return { key: key, data: sourceStats[key] }; })
          .filter(function (item) { return item.data.count > 1; });

        if (duplicateSources.length) {
          consoleProxy.info('[dyn-snippet] Duplicate originating records (model/id pairs) were received from the server.', duplicateSources);
        }
      }

      var observer = new MutationObserver(function (mutations) {
        for (var i = 0; i < mutations.length; i++) {
          var mutation = mutations[i];
          if (mutation.addedNodes && mutation.addedNodes.length) {
            consoleProxy.info('[dyn-snippet] Mutation detected; scheduling recount.');
            setTimeout(countItems, 0);
            break;
          }
        }
      });

      observer.observe(sec, { childList: true, subtree: true });

      consoleProxy.info('[dyn-snippet] Diagnostics observer attached; awaiting render events.');

      requestFrame(function () {
        setTimeout(countItems, 0);
      });
    } catch (err) {
      consoleProxy.error('[dyn-snippet] Diagnostics bootstrap failed:', err && err.stack ? err.stack : err);
    } finally {
      consoleProxy.groupEnd();
    }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', bootstrapDiagnostics, { once: true });
  } else {
    requestFrame(bootstrapDiagnostics);
  }
})();
